from solution import smallest_num
import inspect


def test_issue_example():
    """Find smallest number in a list."""
    assert smallest_num([10, 20, 1, 45, 99]) == 1  # min(10,20,1,45,99)=1


def test_issue_single_element():
    """Find smallest number in a list."""
    assert smallest_num([42]) == 42  # min(42)=42


def test_issue_min_first():
    """Find smallest number in a list."""
    assert smallest_num([1, 5, 9]) == 1  # min(1,5,9)=1


def test_issue_min_last():
    """Find smallest number in a list."""
    assert smallest_num([5, 9, 2]) == 2  # min(5,9,2)=2


def test_issue_negative_and_zero():
    """Find smallest number in a list."""
    assert smallest_num([-5, 0, -10, -1]) == -10  # min(-5,0,-10,-1)=-10


def test_issue_floats():
    """Find smallest number in a list."""
    assert smallest_num([2.5, 1.5, 3.0]) == 1.5  # min(2.5,1.5,3.0)=1.5


def test_issue_duplicate_minima():
    """Find smallest number in a list."""
    assert smallest_num([5, 2, 7, 2]) == 2  # min(5,2,7,2)=2


def test_issue_descending_order():
    """Find smallest number in a list."""
    assert smallest_num([9, 7, 5, 3]) == 3  # min(9,7,5,3)=3


def test_issue_all_equal():
    """Find smallest number in a list."""
    assert smallest_num([7, 7, 7]) == 7  # min(7,7,7)=7


def test_issue_two_elements_second_smaller():
    """Find smallest number in a list."""
    assert smallest_num([100, 99]) == 99  # min(100,99)=99


def test_contract_callable():
    """Public interface exposes smallest_num in solution."""
    assert callable(smallest_num)  # callable==True so literal True holds


def test_contract_single_parameter():
    """Public interface defines smallest_num(xs) with one parameter."""
    assert len(inspect.signature(smallest_num).parameters) == 1  # params: xs = 1
